-- Personal presentation and navigation only. No RMA/session/stock/financial writes.
CREATE TABLE return_assistant_settings (
 tenant_id uuid NOT NULL REFERENCES tenants,owner_id uuid NOT NULL REFERENCES users,version bigint NOT NULL CHECK(version>0),settings_values jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,owner_id)
);
CREATE TABLE return_assistant_queues (
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,owner_id uuid NOT NULL REFERENCES users,version bigint NOT NULL CHECK(version>0),
 item_count integer NOT NULL CHECK(item_count BETWEEN 1 AND 200),position integer NOT NULL CHECK(position>=0 AND position<item_count),skipped_return_ids jsonb NOT NULL,navigation jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,id,owner_id)
);
CREATE INDEX return_assistant_queues_page ON return_assistant_queues(tenant_id,owner_id,created_at DESC,id DESC);
CREATE TABLE return_assistant_queue_items (
 tenant_id uuid NOT NULL,queue_id uuid NOT NULL,owner_id uuid NOT NULL,index integer NOT NULL CHECK(index BETWEEN 0 AND 199),return_id uuid NOT NULL,
 PRIMARY KEY(tenant_id,queue_id,index),UNIQUE(tenant_id,queue_id,return_id),
 FOREIGN KEY(tenant_id,queue_id,owner_id) REFERENCES return_assistant_queues(tenant_id,id,owner_id),FOREIGN KEY(tenant_id,return_id) REFERENCES return_cases(tenant_id,id)
);
CREATE TABLE return_assistant_queue_operations (
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,owner_id uuid NOT NULL REFERENCES users,api_key_id uuid,client_key uuid NOT NULL,
 kind text NOT NULL CHECK(kind IN('settings','create','update')),queue_id uuid,request_hash text NOT NULL CHECK(request_hash~'^[a-f0-9]{64}$'),request jsonb NOT NULL,result jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,client_key),
 FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id),FOREIGN KEY(tenant_id,queue_id,owner_id) REFERENCES return_assistant_queues(tenant_id,id,owner_id),CHECK((kind='settings')=(queue_id IS NULL))
);
CREATE TABLE return_assistant_queue_admissions (
 tenant_id uuid NOT NULL,transaction_id xid8 NOT NULL,operation_id uuid NOT NULL,owner_id uuid NOT NULL,api_key_id uuid,kind text NOT NULL,queue_id uuid,
 before_row jsonb,after_row jsonb NOT NULL,manifest jsonb NOT NULL,request jsonb NOT NULL,request_hash text NOT NULL,
 PRIMARY KEY(tenant_id,transaction_id,operation_id),FOREIGN KEY(tenant_id,operation_id) REFERENCES return_assistant_queue_operations(tenant_id,id) DEFERRABLE INITIALLY DEFERRED
);
DO $$DECLARE rel text;BEGIN FOREACH rel IN ARRAY ARRAY['return_assistant_settings','return_assistant_queues','return_assistant_queue_items','return_assistant_queue_operations','return_assistant_queue_admissions'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',rel);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',rel);
 EXECUTE format('CREATE POLICY tenant_scope ON %I TO dyna_app USING(tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',rel);
 EXECUTE format('CREATE POLICY owner_scope ON %I TO %I USING(true) WITH CHECK(true)',rel,current_user);
 -- Personal rows are not generally SELECT granted: typed readers also bind the current owner.
 EXECUTE format('REVOKE ALL ON %I FROM PUBLIC,dyna_app',rel);
END LOOP;END $$;
CREATE FUNCTION return_assistant_queue_installed() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$SELECT EXISTS(SELECT 1 FROM migrations WHERE name='140_return_assistant_queues')$$;
CREATE FUNCTION return_assistant_queue_defaults() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public,pg_temp AS $$SELECT '{"auto_next":false,"hide_accepted":false,"name_source":"historical","product_sort":"historical","thumbnail_size":"none","case_fields":["number","order_number","created_at","kind"],"product_fields":["sku","name","quantity","line_total"]}'::jsonb$$;
CREATE FUNCTION return_assistant_queue_navigation(v jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public,pg_temp AS $$SELECT coalesce(jsonb_typeof(v)='object' AND v-ARRAY['auto_next','hide_accepted']='{}'::jsonb AND jsonb_typeof(v->'auto_next')='boolean' AND jsonb_typeof(v->'hide_accepted')='boolean',false)$$;
CREATE FUNCTION return_assistant_queue_values(v jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=public,pg_temp AS $$DECLARE field text;allowed text[];parts jsonb;BEGIN
 IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR v-ARRAY['auto_next','hide_accepted','name_source','product_sort','thumbnail_size','case_fields','product_fields']<>'{}'::jsonb OR NOT return_assistant_queue_navigation(jsonb_build_object('auto_next',v->'auto_next','hide_accepted',v->'hide_accepted')) OR coalesce(v->>'name_source','') NOT IN('historical','current') OR coalesce(v->>'product_sort','') NOT IN('historical','name','sku') OR coalesce(v->>'thumbnail_size','') NOT IN('none','small','large') THEN RETURN false;END IF;
 FOREACH field IN ARRAY ARRAY['case_fields','product_fields'] LOOP
 parts:=v->field;allowed:=CASE WHEN field='case_fields' THEN ARRAY['number','order_number','created_at','kind','customer','commercial_value'] ELSE ARRAY['sku','name','quantity','line_total','ean','components','locations','stock'] END;
 IF jsonb_typeof(parts) IS DISTINCT FROM 'array' THEN RETURN false;END IF;
 IF jsonb_array_length(parts)>cardinality(allowed) OR EXISTS(SELECT 1 FROM jsonb_array_elements(parts) e WHERE jsonb_typeof(e)<>'string' OR NOT(e#>>'{}'=ANY(allowed))) OR(SELECT count(DISTINCT e) FROM jsonb_array_elements(parts)e)<>jsonb_array_length(parts) THEN RETURN false;END IF;
 END LOOP;RETURN true;
END $$;
CREATE FUNCTION return_assistant_queue_lock() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public,pg_temp AS $$SELECT pg_advisory_xact_lock(hashtextextended('return.assistant.queues:'||current_setting('app.tenant_id'),0))$$;
CREATE FUNCTION return_assistant_queue_budget() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;n bigint;BEGIN
 IF(SELECT count(*) FROM return_assistant_queues WHERE tenant_id=t)>2000 OR(SELECT count(*) FROM return_assistant_queue_operations WHERE tenant_id=t)>10000 THEN RAISE EXCEPTION 'Limit historii kolejki asystenta' USING ERRCODE='23514';END IF;
 SELECT coalesce(sum(z.bytes),0) INTO n FROM(SELECT octet_length(to_jsonb(x)::text) bytes FROM return_assistant_settings x WHERE tenant_id=t UNION ALL SELECT octet_length(to_jsonb(x)::text) FROM return_assistant_queues x WHERE tenant_id=t UNION ALL SELECT octet_length(to_jsonb(x)::text) FROM return_assistant_queue_items x WHERE tenant_id=t UNION ALL SELECT octet_length(to_jsonb(x)::text) FROM return_assistant_queue_operations x WHERE tenant_id=t UNION ALL SELECT octet_length(to_jsonb(x)::text) FROM return_assistant_queue_admissions x WHERE tenant_id=t)z;
 IF n>67108864 THEN RAISE EXCEPTION 'Limit danych kolejki asystenta' USING ERRCODE='23514';END IF;
END $$;
CREATE FUNCTION return_assistant_queue_head(q return_assistant_queues) RETURNS jsonb LANGUAGE sql STABLE SET search_path=public,pg_temp AS $$SELECT jsonb_build_object('id',q.id,'version',q.version::text,'count',q.item_count,'position',q.position,'skipped_return_ids',q.skipped_return_ids,'navigation',q.navigation,'created_at',q.created_at,'updated_at',q.updated_at)$$;
CREATE FUNCTION return_assistant_queue_read(uid uuid,kid uuid,op text,qid uuid DEFAULT NULL,cur uuid DEFAULT NULL,lim integer DEFAULT 50) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;s return_assistant_settings;q return_assistant_queues;page_rows jsonb;more boolean;ci integer;BEGIN
 PERFORM return_assistant_queue_require(uid,kid,false,false);IF lim NOT BETWEEN 1 AND 50 OR lim IS NULL THEN RAISE EXCEPTION 'Nieprawidłowy limit kolejki' USING ERRCODE='23514';END IF;
 IF op='settings' THEN SELECT * INTO s FROM return_assistant_settings WHERE(tenant_id,owner_id)=(t,uid);RETURN jsonb_build_object('settings',jsonb_build_object('version',coalesce(s.version::text,'0'),'values',coalesce(s.settings_values,return_assistant_queue_defaults())));END IF;
 IF op='list' THEN
 IF cur IS NOT NULL AND NOT EXISTS(SELECT 1 FROM return_assistant_queues WHERE(tenant_id,owner_id,id)=(t,uid,cur)) THEN RAISE EXCEPTION 'Kursor nie należy do własnej kolejki' USING ERRCODE='P0002';END IF;
 SELECT coalesce(jsonb_agg(return_assistant_queue_head(jsonb_populate_record(NULL::return_assistant_queues,to_jsonb(z))) ORDER BY z.created_at DESC,z.id DESC),'[]') INTO page_rows FROM(SELECT a.* FROM return_assistant_queues a WHERE(a.tenant_id,a.owner_id)=(t,uid) AND(cur IS NULL OR(a.created_at,a.id)<(SELECT b.created_at,b.id FROM return_assistant_queues b WHERE(b.tenant_id,b.owner_id,b.id)=(t,uid,cur))) ORDER BY a.created_at DESC,a.id DESC LIMIT lim+1)z;
 more:=jsonb_array_length(page_rows)>lim;IF more THEN page_rows:=page_rows-(jsonb_array_length(page_rows)-1);END IF;RETURN jsonb_build_object('data',page_rows,'next_cursor',CASE WHEN more THEN page_rows->(lim-1)->>'id' ELSE NULL END);
 END IF;
 SELECT * INTO q FROM return_assistant_queues WHERE(tenant_id,owner_id,id)=(t,uid,qid);IF q.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono własnej kolejki' USING ERRCODE='P0002';END IF;
 IF op='detail' THEN RETURN jsonb_build_object('queue',return_assistant_queue_head(q));END IF;
 IF op IS DISTINCT FROM 'items' THEN RAISE EXCEPTION 'Nieprawidłowy odczyt kolejki' USING ERRCODE='23514';END IF;
 ci:=-1;IF cur IS NOT NULL THEN SELECT x.index INTO ci FROM return_assistant_queue_items x WHERE(x.tenant_id,x.queue_id,x.return_id)=(t,qid,cur);IF ci IS NULL THEN RAISE EXCEPTION 'Kursor nie należy do własnego manifestu' USING ERRCODE='P0002';END IF;END IF;
 SELECT coalesce(jsonb_agg(z.item ORDER BY z.idx),'[]') INTO page_rows FROM(SELECT qi.index idx,jsonb_build_object('index',qi.index,'return_id',rc.id,'number',rc.number,'order_id',rc.order_id,'order_number',o.number,'kind',rc.kind,'state',rc.state,'created_at',rc.created_at,'accepted',(rc.received_at IS NOT NULL OR public.b2b_dropship_return_acceptance(rc.id)->>'accepted_at' IS NOT NULL) AND rc.state IN('refund_pending','closed'),'skipped',q.skipped_return_ids @> jsonb_build_array(rc.id),'current_session',(SELECT jsonb_build_object('id',ss.id,'state',ss.state,'owner_id',ss.actor_id,'lease_expires_at',ss.lease_expires_at) FROM return_assistant_sessions ss WHERE(ss.tenant_id,ss.return_id)=(t,rc.id) ORDER BY ss.created_at DESC,ss.id DESC LIMIT 1),'receipt_id',(SELECT rr.id FROM return_assistant_receipts rr WHERE(rr.tenant_id,rr.return_id)=(t,rc.id))) item FROM return_assistant_queue_items qi JOIN return_cases rc ON(rc.tenant_id,rc.id)=(qi.tenant_id,qi.return_id) JOIN orders o ON(o.tenant_id,o.id)=(rc.tenant_id,rc.order_id) WHERE(qi.tenant_id,qi.queue_id)=(t,qid) AND qi.index>ci ORDER BY qi.index LIMIT lim+1)z;
 more:=jsonb_array_length(page_rows)>lim;IF more THEN page_rows:=page_rows-(jsonb_array_length(page_rows)-1);END IF;RETURN jsonb_build_object('queue',return_assistant_queue_head(q),'data',page_rows,'next_cursor',CASE WHEN more THEN page_rows->(lim-1)->>'return_id' ELSE NULL END);
END $$;
CREATE FUNCTION return_assistant_queue_write(eid uuid,uid uuid,kid uuid,op text,qid uuid,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;r return_assistant_queue_operations;s return_assistant_settings;q return_assistant_queues;before_json jsonb;after_json jsonb;manifest_json jsonb:='[]';h text;result_json jsonb;dt timestamptz:=clock_timestamp();new_version bigint;BEGIN
 PERFORM return_assistant_queue_require(uid,kid,true,false);PERFORM return_assistant_queue_lock();
 IF jsonb_typeof(b) IS DISTINCT FROM 'object' OR coalesce(b->>'client_key','')!~'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' OR op IS NULL OR op NOT IN('settings','create','update') THEN RAISE EXCEPTION 'Nieprawidłowa operacja kolejki' USING ERRCODE='23514';END IF;
 h:=return_assistant_hash(jsonb_build_object('kind',op,'queue_id',CASE WHEN op='update' THEN qid ELSE NULL END,'body',b));
 SELECT * INTO r FROM return_assistant_queue_operations WHERE(tenant_id,client_key)=(t,(b->>'client_key')::uuid);
 IF r.id IS NOT NULL THEN IF(r.owner_id,r.api_key_id,r.kind,r.request_hash) IS DISTINCT FROM(uid,kid,op,h) THEN RAISE EXCEPTION 'Klucz operacji kolejki ma inną treść lub właściciela' USING ERRCODE='23514';END IF;RETURN r.result||jsonb_build_object('operation_id',r.id,'reused',true);END IF;
 IF op='settings' THEN
 IF b-ARRAY['client_key','version','values']<>'{}'::jsonb OR NOT return_assistant_queue_values(b->'values') OR coalesce(b->>'version','')!~'^(0|[1-9][0-9]{0,18})$' THEN RAISE EXCEPTION 'Nieprawidłowe ustawienia asystenta' USING ERRCODE='23514';END IF;
 SELECT * INTO s FROM return_assistant_settings WHERE(tenant_id,owner_id)=(t,uid) FOR UPDATE;before_json:=CASE WHEN s.owner_id IS NULL THEN NULL ELSE to_jsonb(s) END;
 IF coalesce(s.version::text,'0') IS DISTINCT FROM b->>'version' THEN RAISE EXCEPTION 'Ustawienia wymagają świeżej wersji' USING ERRCODE='23514';END IF;
 new_version:=coalesce(s.version,0)+1;s.tenant_id:=t;s.owner_id:=uid;s.version:=new_version;s.settings_values:=b->'values';s.created_at:=coalesce(s.created_at,dt);s.updated_at:=dt;after_json:=to_jsonb(s);result_json:=jsonb_build_object('settings',jsonb_build_object('version',s.version::text,'values',s.settings_values));
 ELSIF op='create' THEN
 IF qid IS NULL OR b-ARRAY['client_key','return_ids','navigation']<>'{}'::jsonb OR jsonb_typeof(b->'return_ids') IS DISTINCT FROM 'array' OR NOT return_assistant_queue_navigation(b->'navigation') THEN RAISE EXCEPTION 'Nieprawidłowy manifest kolejki' USING ERRCODE='23514';END IF;
 manifest_json:=b->'return_ids';IF jsonb_array_length(manifest_json) NOT BETWEEN 1 AND 200 OR EXISTS(SELECT 1 FROM jsonb_array_elements(manifest_json)x WHERE jsonb_typeof(x)<>'string' OR coalesce(x#>>'{}','')!~'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$') OR(SELECT count(DISTINCT x) FROM jsonb_array_elements(manifest_json)x)<>jsonb_array_length(manifest_json) THEN RAISE EXCEPTION 'Nieprawidłowe lub powtórzone RMA' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(manifest_json)x WHERE NOT EXISTS(SELECT 1 FROM return_cases rc WHERE(rc.tenant_id,rc.id)=(t,x::uuid))) THEN RAISE EXCEPTION 'Nie znaleziono własnego RMA' USING ERRCODE='P0002';END IF;
 q.id:=qid;q.tenant_id:=t;q.owner_id:=uid;q.version:=1;q.item_count:=jsonb_array_length(manifest_json);q.position:=0;q.skipped_return_ids:='[]';q.navigation:=b->'navigation';q.created_at:=dt;q.updated_at:=dt;after_json:=to_jsonb(q);result_json:=jsonb_build_object('queue',return_assistant_queue_head(q));
 ELSE
 SELECT * INTO q FROM return_assistant_queues WHERE(tenant_id,owner_id,id)=(t,uid,qid) FOR UPDATE;IF q.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono własnej kolejki' USING ERRCODE='P0002';END IF;
 IF b-ARRAY['client_key','version','position','skipped_return_ids','navigation']<>'{}'::jsonb OR coalesce(b->>'version','')!~'^[1-9][0-9]{0,18}$' OR jsonb_typeof(b->'position') IS DISTINCT FROM 'number' OR coalesce(b->>'position','')!~'^(0|[1-9][0-9]{0,2})$' OR jsonb_typeof(b->'skipped_return_ids') IS DISTINCT FROM 'array' OR NOT return_assistant_queue_navigation(b->'navigation') THEN RAISE EXCEPTION 'Nieprawidłowa zmiana kolejki' USING ERRCODE='23514';END IF;
 IF q.version::text IS DISTINCT FROM b->>'version' OR(b->>'position')::int NOT BETWEEN 0 AND q.item_count-1 THEN RAISE EXCEPTION 'Kolejka wymaga świeżej wersji i pozycji' USING ERRCODE='23514';END IF;
 IF jsonb_array_length(b->'skipped_return_ids')>q.item_count OR(SELECT count(DISTINCT x) FROM jsonb_array_elements(b->'skipped_return_ids')x)<>jsonb_array_length(b->'skipped_return_ids') OR EXISTS(SELECT 1 FROM jsonb_array_elements(b->'skipped_return_ids')x WHERE NOT EXISTS(SELECT 1 FROM return_assistant_queue_items qi WHERE(qi.tenant_id,qi.queue_id)=(t,qid) AND to_jsonb(qi.return_id)=x)) THEN RAISE EXCEPTION 'Pominięcia wymagają własnego manifestu' USING ERRCODE='23514';END IF;
 SELECT jsonb_agg(qi.return_id ORDER BY qi.index) INTO manifest_json FROM return_assistant_queue_items qi WHERE(qi.tenant_id,qi.queue_id)=(t,qid);before_json:=to_jsonb(q);q.version:=q.version+1;q.position:=(b->>'position')::int;q.navigation:=b->'navigation';q.skipped_return_ids:=b->'skipped_return_ids';q.updated_at:=dt;after_json:=to_jsonb(q);result_json:=jsonb_build_object('queue',return_assistant_queue_head(q));
 END IF;
 PERFORM return_assistant_queue_require(uid,kid,true,false);
 INSERT INTO return_assistant_queue_admissions VALUES(t,pg_current_xact_id(),eid,uid,kid,op,CASE WHEN op='settings' THEN NULL ELSE qid END,before_json,after_json,manifest_json,b,h);
 IF op='settings' THEN IF before_json IS NULL THEN INSERT INTO return_assistant_settings SELECT s.*;ELSE UPDATE return_assistant_settings SET version=s.version,settings_values=s.settings_values,updated_at=s.updated_at WHERE(tenant_id,owner_id)=(t,uid);END IF;
 ELSIF op='create' THEN INSERT INTO return_assistant_queues SELECT q.*;INSERT INTO return_assistant_queue_items SELECT t,qid,uid,(x.ordinality-1)::int,x.id::uuid FROM jsonb_array_elements_text(manifest_json) WITH ORDINALITY x(id,ordinality);
 ELSE UPDATE return_assistant_queues SET version=q.version,position=q.position,skipped_return_ids=q.skipped_return_ids,navigation=q.navigation,updated_at=q.updated_at WHERE(tenant_id,id)=(t,qid);END IF;
 INSERT INTO return_assistant_queue_operations(id,tenant_id,owner_id,api_key_id,client_key,kind,queue_id,request_hash,request,result) VALUES(eid,t,uid,kid,(b->>'client_key')::uuid,op,CASE WHEN op='settings' THEN NULL ELSE qid END,h,b,result_json);
 PERFORM return_assistant_queue_budget();RETURN result_json||jsonb_build_object('operation_id',eid,'reused',false);
END $$;
CREATE FUNCTION return_assistant_queue_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE a return_assistant_queue_admissions;v jsonb;BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Historia kolejki asystenta jest trwała' USING ERRCODE='23514';END IF;v:=to_jsonb(NEW);
 IF TG_TABLE_NAME IN('return_assistant_queue_operations','return_assistant_queue_items') AND TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Manifest i pokwitowanie kolejki są niezmienne' USING ERRCODE='23514';END IF;
 IF TG_TABLE_NAME='return_assistant_queue_items' THEN
 IF NOT EXISTS(SELECT 1 FROM return_assistant_queue_admissions ad WHERE(ad.tenant_id,ad.transaction_id,ad.kind,ad.queue_id,ad.owner_id)=(NEW.tenant_id,pg_current_xact_id(),'create',NEW.queue_id,NEW.owner_id) AND ad.manifest->NEW.index=to_jsonb(NEW.return_id)) THEN RAISE EXCEPTION 'Manifest wymaga bieżącej zgody kolejki' USING ERRCODE='23514';END IF;RETURN NEW;END IF;
 IF TG_TABLE_NAME='return_assistant_queue_operations' THEN SELECT * INTO a FROM return_assistant_queue_admissions ad WHERE(ad.tenant_id,ad.transaction_id,ad.operation_id)=(NEW.tenant_id,pg_current_xact_id(),NEW.id);
 IF a.operation_id IS NULL OR(a.owner_id,a.api_key_id,a.kind,a.queue_id,a.request_hash,a.request) IS DISTINCT FROM(NEW.owner_id,NEW.api_key_id,NEW.kind,NEW.queue_id,NEW.request_hash,NEW.request) OR NEW.client_key IS DISTINCT FROM(a.request->>'client_key')::uuid OR NEW.result IS DISTINCT FROM(CASE WHEN a.kind='settings' THEN jsonb_build_object('settings',jsonb_build_object('version',a.after_row->>'version','values',a.after_row->'settings_values')) ELSE jsonb_build_object('queue',return_assistant_queue_head(jsonb_populate_record(NULL::return_assistant_queues,a.after_row))) END) THEN RAISE EXCEPTION 'Pokwitowanie wymaga dokładnej zgody kolejki' USING ERRCODE='23514';END IF;RETURN NEW;END IF;
 SELECT * INTO a FROM return_assistant_queue_admissions ad WHERE(ad.tenant_id,ad.transaction_id,ad.owner_id)=(NEW.tenant_id,pg_current_xact_id(),NEW.owner_id) AND ad.after_row=v AND(ad.kind='settings')=(TG_TABLE_NAME='return_assistant_settings');
 IF a.operation_id IS NULL THEN RAISE EXCEPTION 'Zmiana wymaga bieżącej zgody kolejki' USING ERRCODE='23514';END IF;
 IF TG_OP='UPDATE' THEN IF a.before_row IS DISTINCT FROM to_jsonb(OLD) THEN RAISE EXCEPTION 'Zmiana wymaga dokładnej wersji kolejki' USING ERRCODE='23514';END IF;ELSIF a.before_row IS NOT NULL THEN RAISE EXCEPTION 'Narodziny wymagają nowej kolejki' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
CREATE FUNCTION return_assistant_queue_immutable() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$BEGIN RAISE EXCEPTION 'Zgoda kolejki jest niezmienna' USING ERRCODE='23514';END $$;
CREATE FUNCTION return_assistant_queue_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$DECLARE a return_assistant_queue_admissions;cur jsonb;manifest_json jsonb;BEGIN
 SELECT * INTO a FROM return_assistant_queue_admissions WHERE(tenant_id,transaction_id,operation_id)=(NEW.tenant_id,NEW.transaction_id,NEW.operation_id);
 IF NOT EXISTS(SELECT 1 FROM return_assistant_queue_operations r WHERE(r.tenant_id,r.id,r.owner_id,r.request_hash,r.request)=(a.tenant_id,a.operation_id,a.owner_id,a.request_hash,a.request) AND r.api_key_id IS NOT DISTINCT FROM a.api_key_id AND r.queue_id IS NOT DISTINCT FROM a.queue_id AND r.kind=a.kind) THEN RAISE EXCEPTION 'Niekompletne pokwitowanie kolejki' USING ERRCODE='23514';END IF;
 IF a.kind<>'settings' THEN SELECT jsonb_agg(qi.return_id ORDER BY qi.index) INTO manifest_json FROM return_assistant_queue_items qi WHERE(qi.tenant_id,qi.queue_id)=(a.tenant_id,a.queue_id);IF manifest_json IS DISTINCT FROM a.manifest THEN RAISE EXCEPTION 'Niekompletny manifest kolejki' USING ERRCODE='23514';END IF;END IF;
 IF a.kind='settings' THEN SELECT to_jsonb(s) INTO cur FROM return_assistant_settings s WHERE(s.tenant_id,s.owner_id)=(a.tenant_id,a.owner_id);ELSE SELECT to_jsonb(q) INTO cur FROM return_assistant_queues q WHERE(q.tenant_id,q.id)=(a.tenant_id,a.queue_id);END IF;
 IF cur IS DISTINCT FROM a.after_row AND NOT EXISTS(SELECT 1 FROM return_assistant_queue_admissions later WHERE(later.tenant_id,later.transaction_id,later.owner_id)=(a.tenant_id,a.transaction_id,a.owner_id) AND later.queue_id IS NOT DISTINCT FROM a.queue_id AND later.after_row=cur AND(later.after_row->>'version')::bigint>(a.after_row->>'version')::bigint) THEN RAISE EXCEPTION 'Stan kolejki nie zgadza się z pokwitowaniem' USING ERRCODE='23514';END IF;
 PERFORM return_assistant_queue_require(a.owner_id,a.api_key_id,true,false);PERFORM return_assistant_queue_budget();RETURN NULL;
END $$;
DO $$DECLARE rel text;BEGIN FOREACH rel IN ARRAY ARRAY['return_assistant_settings','return_assistant_queues','return_assistant_queue_items','return_assistant_queue_operations'] LOOP EXECUTE format('CREATE TRIGGER return_assistant_queue_guard BEFORE INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION return_assistant_queue_guard()',rel);END LOOP;END $$;
CREATE TRIGGER return_assistant_queue_admission_immutable BEFORE UPDATE OR DELETE ON return_assistant_queue_admissions FOR EACH ROW EXECUTE FUNCTION return_assistant_queue_immutable();
CREATE CONSTRAINT TRIGGER return_assistant_queue_complete AFTER INSERT ON return_assistant_queue_admissions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION return_assistant_queue_complete();
CREATE FUNCTION return_assistant_queue_guards() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$SELECT
 NOT EXISTS(SELECT 1 FROM unnest(ARRAY['return_assistant_settings','return_assistant_queues','return_assistant_queue_items','return_assistant_queue_operations','return_assistant_queue_admissions'])x(name) LEFT JOIN pg_class c ON c.oid=to_regclass('public.'||x.name) WHERE c.oid IS NULL OR NOT c.relrowsecurity OR NOT c.relforcerowsecurity OR NOT EXISTS(SELECT 1 FROM pg_policy p WHERE p.polrelid=c.oid AND p.polname='tenant_scope') OR NOT EXISTS(SELECT 1 FROM pg_policy p WHERE p.polrelid=c.oid AND p.polname='owner_scope') OR has_table_privilege('dyna_app',c.oid,'SELECT,INSERT,UPDATE,DELETE') OR has_any_column_privilege('dyna_app',c.oid,'SELECT,INSERT,UPDATE'))
 AND NOT EXISTS(SELECT 1 FROM(VALUES
 ('return_assistant_settings',ARRAY['tenant_id','owner_id','version','settings_values','created_at','updated_at']),
 ('return_assistant_queues',ARRAY['id','tenant_id','owner_id','version','item_count','position','skipped_return_ids','navigation','created_at','updated_at']),
 ('return_assistant_queue_items',ARRAY['tenant_id','queue_id','owner_id','index','return_id']),
 ('return_assistant_queue_operations',ARRAY['id','tenant_id','owner_id','api_key_id','client_key','kind','queue_id','request_hash','request','result','created_at']),
 ('return_assistant_queue_admissions',ARRAY['tenant_id','transaction_id','operation_id','owner_id','api_key_id','kind','queue_id','before_row','after_row','manifest','request','request_hash']))expected(rel,cols)
 CROSS JOIN LATERAL unnest(expected.cols)name WHERE NOT EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=to_regclass('public.'||expected.rel) AND a.attname=name AND NOT a.attisdropped AND a.attnum>0))
 AND(SELECT count(*) FROM pg_trigger tr WHERE NOT tr.tgisinternal AND tr.tgenabled='O' AND tr.tgname='return_assistant_queue_guard' AND tr.tgfoid='return_assistant_queue_guard()'::regprocedure AND tr.tgrelid=ANY(ARRAY['return_assistant_settings'::regclass,'return_assistant_queues'::regclass,'return_assistant_queue_items'::regclass,'return_assistant_queue_operations'::regclass]))=4
 AND EXISTS(SELECT 1 FROM pg_trigger tr WHERE tr.tgrelid='return_assistant_queue_admissions'::regclass AND tr.tgname='return_assistant_queue_admission_immutable' AND tr.tgfoid='return_assistant_queue_immutable()'::regprocedure AND tr.tgenabled='O')
 AND EXISTS(SELECT 1 FROM pg_trigger tr WHERE tr.tgrelid='return_assistant_queue_admissions'::regclass AND tr.tgname='return_assistant_queue_complete' AND tr.tgfoid='return_assistant_queue_complete()'::regprocedure AND tr.tgenabled='O' AND tr.tgdeferrable AND tr.tginitdeferred)
 AND NOT EXISTS(SELECT 1 FROM pg_constraint con WHERE con.conrelid=ANY(ARRAY['return_assistant_settings'::regclass,'return_assistant_queues'::regclass,'return_assistant_queue_items'::regclass,'return_assistant_queue_operations'::regclass,'return_assistant_queue_admissions'::regclass]) AND NOT con.convalidated)
 AND(SELECT count(*) FROM pg_constraint con WHERE con.conrelid=ANY(ARRAY['return_assistant_settings'::regclass,'return_assistant_queues'::regclass,'return_assistant_queue_items'::regclass,'return_assistant_queue_operations'::regclass,'return_assistant_queue_admissions'::regclass]) AND con.contype IN('p','u'))=10
 AND(SELECT count(*) FROM pg_constraint con WHERE con.conrelid=ANY(ARRAY['return_assistant_settings'::regclass,'return_assistant_queues'::regclass,'return_assistant_queue_items'::regclass,'return_assistant_queue_operations'::regclass,'return_assistant_queue_admissions'::regclass]) AND con.contype='c')=8
 AND NOT EXISTS(SELECT * FROM(VALUES
 ('return_assistant_settings','tenant_id','tenants','id'),('return_assistant_settings','owner_id','users','id'),('return_assistant_queues','tenant_id','tenants','id'),('return_assistant_queues','owner_id','users','id'),
 ('return_assistant_queue_items','tenant_id,queue_id,owner_id','return_assistant_queues','tenant_id,id,owner_id'),('return_assistant_queue_items','tenant_id,return_id','return_cases','tenant_id,id'),
 ('return_assistant_queue_operations','tenant_id','tenants','id'),('return_assistant_queue_operations','owner_id','users','id'),('return_assistant_queue_operations','tenant_id,api_key_id','api_keys','tenant_id,id'),('return_assistant_queue_operations','tenant_id,queue_id,owner_id','return_assistant_queues','tenant_id,id,owner_id'),
 ('return_assistant_queue_admissions','tenant_id,operation_id','return_assistant_queue_operations','tenant_id,id'))expected(rel,cols,target,target_cols)
 WHERE NOT EXISTS(SELECT 1 FROM pg_constraint con WHERE con.conrelid=to_regclass('public.'||expected.rel) AND con.confrelid=to_regclass('public.'||expected.target) AND con.contype='f' AND con.convalidated AND(SELECT string_agg(a.attname,',' ORDER BY k.ordinality) FROM unnest(con.conkey) WITH ORDINALITY k(num,ordinality) JOIN pg_attribute a ON(a.attrelid,a.attnum)=(con.conrelid,k.num))=expected.cols AND(SELECT string_agg(a.attname,',' ORDER BY k.ordinality) FROM unnest(con.confkey) WITH ORDINALITY k(num,ordinality) JOIN pg_attribute a ON(a.attrelid,a.attnum)=(con.confrelid,k.num))=expected.target_cols))
 AND EXISTS(SELECT 1 FROM pg_constraint con WHERE con.conrelid='return_assistant_queue_admissions'::regclass AND con.contype='f' AND con.condeferrable AND con.condeferred)
 AND NOT EXISTS(SELECT 1 FROM unnest(ARRAY['return_assistant_queue_installed()','return_assistant_queue_require(uuid,uuid,boolean,boolean)','return_assistant_queue_defaults()','return_assistant_queue_navigation(jsonb)','return_assistant_queue_values(jsonb)','return_assistant_queue_lock()','return_assistant_queue_budget()','return_assistant_queue_head(return_assistant_queues)','return_assistant_queue_read(uuid,uuid,text,uuid,uuid,integer)','return_assistant_queue_write(uuid,uuid,uuid,text,uuid,jsonb)','return_assistant_queue_guard()','return_assistant_queue_immutable()','return_assistant_queue_complete()','return_assistant_queue_guards()'])x(name) WHERE to_regprocedure(x.name) IS NULL)
 AND NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace ns ON ns.oid=p.pronamespace WHERE ns.nspname='public' AND p.proname LIKE 'return_assistant_queue_%' AND(
 EXISTS(SELECT 1 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl WHERE acl.grantee=0 AND acl.privilege_type='EXECUTE')
 OR has_function_privilege('dyna_app',p.oid,'EXECUTE') IS DISTINCT FROM(p.proname IN('return_assistant_queue_installed','return_assistant_queue_guards','return_assistant_queue_read','return_assistant_queue_write'))))
$$;
CREATE FUNCTION return_assistant_queue_require(uid uuid,kid uuid,writing boolean,pin boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$BEGIN
 IF NOT return_assistant_queue_installed() OR NOT return_assistant_queue_guards() THEN RAISE EXCEPTION 'Niekompletna kolejka asystenta' USING ERRCODE='55000';END IF;RETURN return_assistant_require(uid,kid,writing,pin);
END $$;
DO $$DECLARE fn record;BEGIN FOR fn IN SELECT p.oid::regprocedure signature FROM pg_proc p JOIN pg_namespace ns ON ns.oid=p.pronamespace WHERE ns.nspname='public' AND p.proname LIKE 'return_assistant_queue_%' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,dyna_app',fn.signature);END LOOP;END $$;
GRANT EXECUTE ON FUNCTION return_assistant_queue_installed(),return_assistant_queue_guards(),return_assistant_queue_read(uuid,uuid,text,uuid,uuid,integer),return_assistant_queue_write(uuid,uuid,uuid,text,uuid,jsonb) TO dyna_app;
